# enumerate maximal row-band rectangles for solid colors, width and height >=5
R,C=len(grid),len(grid[0]); rects=[]
for r0 in range(R):
 for r1 in range(r0+4,R):
  for c0 in range(C):
   v=grid[r0][c0];
   for c1 in range(c0+4,C):
    if all(grid[r][c]==v for r in range(r0,r1+1) for c in range(c0,c1+1)):
     # maximal if can't extend any side same color
     if (r0==0 or any(grid[r0-1][c]!=v for c in range(c0,c1+1))) and (r1==R-1 or any(grid[r1+1][c]!=v for c in range(c0,c1+1))) and (c0==0 or any(grid[r][c0-1]!=v for r in range(r0,r1+1))) and (c1==C-1 or any(grid[r][c1+1]!=v for r in range(r0,r1+1))):
      rects.append((r0,r1,c0,c1,v))
print(rects[:50],len(rects))

out=[row[:] for row in grid]
for r0,r1,c0,c1,v in rects:
 for r in range(r0,r1+1):
  for c in range(c0,c1+1): out[r][c]=4
import json
print(json.dumps(out,separators=(',',':')))

